package ama.transcript;

import ama.access.MeetingAccess;
import ama.contract.IdentityContracts.Actor;
import ama.contract.FileContracts.*;
import ama.contract.TaskContracts.SubjectRef;
import ama.material.*;
import ama.storage.*;
import ama.task.JdbcSubjectFences;
import ama.task.SubjectFencePort;
import org.springframework.jdbc.core.JdbcTemplate;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import static ama.contract.MinutesContracts.uuid;

/** Real source receipts + append-only parse history + immutable applied selection. I/O is outside DB locks. */
public final class JdbcMaterials {
 private static final int MAX_MATERIALS=64;
 private final JdbcTranscriptAuthority authority;private final JdbcTemplate j;private final FileUploads uploads;private final FileRegistry registry;private final MaterialKnowledge knowledge;private final SubjectFencePort fences;
 private final MaterialParser parser=new MaterialDocumentParser();private final MaterialParser.Budget parseBudget;
 public JdbcMaterials(JdbcTranscriptAuthority authority,FileUploads uploads,ControlledKnowledgeClient client,MaterialParser.Budget budget){this.authority=Objects.requireNonNull(authority);this.uploads=Objects.requireNonNull(uploads);registry=authority.fileRegistry();j=new JdbcTemplate(authority.dataSource());j.setQueryTimeout(2);fences=new JdbcSubjectFences(authority.dataSource(),Set.of("MEETING"));parseBudget=Objects.requireNonNull(budget);knowledge=client==null?null:new MaterialKnowledge(authority,client);}
 public record Selection(String fileId,String libraryId,String documentId,String version){
  public Selection {if(fileId!=null){uuid(fileId);if(libraryId!=null||documentId!=null||version!=null)throw new IllegalArgumentException("Choose one material source");}else{MaterialKnowledge.id(libraryId);MaterialKnowledge.id(documentId);if(version==null||!version.matches("[0-9a-f]{64}"))throw new IllegalArgumentException("Exact knowledge version required");}}
 }
 public record Item(String id,String materialRevisionId,String parsedDocumentId,String fileId,String name,String source,String sourceVersion,String sizeBytesToken,String sha256,String state,String error){}
 public record Listing(List<Item> items,String materialSnapshotId,boolean materialsPending,String meetingRevision){public Listing{items=List.copyOf(items);}}
 private record Root(long revision,long epoch,String snapshot){}
 private record Parse(MaterialParser.Result result,String error,String textFile){}
 private record Source(String file,String hash,String name,String provider,String external,String version){}
 private record Started(Root root,Item replay,Map<String,Object> prior){}
 public Listing list(Actor actor,String meeting){uuid(meeting);return authority.transactionRunner().required(()->{registry.lock(actor,meeting,MeetingAccess.Action.READ);return listing(meeting);});}
 public Map<String,Object> libraries(Actor actor,String meeting,String library,String search,String cursor,int limit)throws IOException{if(knowledge==null)throw failure(503,"MATERIAL_KNOWLEDGE_UNAVAILABLE");return knowledge.page(actor,meeting,library,search,cursor,limit);}
 public Item add(Actor actor,String meeting,String key,Selection selected,String trace)throws IOException {
  uuid(meeting);uuid(trace);JdbcProcessingIntake.key(key);String scope=JdbcProcessingIntake.digest(actor.enterpriseId(),meeting,"MATERIAL_ADD",key),request=JdbcProcessingIntake.digest(Objects.toString(selected.fileId(),""),Objects.toString(selected.libraryId(),""),Objects.toString(selected.documentId(),""),Objects.toString(selected.version(),""));
  var started=start(actor,meeting,scope,request,null);if(started.replay()!=null)return started.replay();
  Source source;
  MaterialParser.Result extracted=null;
  if(selected.fileId()!=null){try(var file=registry.download(actor,selected.fileId(),null)){if(!meeting.equals(file.file().meetingId()))throw new NotFound();source=new Source(file.file().fileId(),file.file().sha256(),file.file().displayName(),null,null,null);}}
  else{if(knowledge==null)throw failure(503,"MATERIAL_KNOWLEDGE_UNAVAILABLE");var document=knowledge.document(actor,meeting,selected.libraryId(),selected.documentId(),selected.version());String file=store(actor,meeting,scope,"knowledge",document.name()+".json",document.bytes(),trace);source=new Source(file,document.version(),document.name(),document.provider(),selected.documentId(),selected.version());byte[] text=document.text().getBytes(StandardCharsets.UTF_8);try{var parsed=parser.parse(new ByteArrayInputStream(text),"knowledge.txt",MaterialDocumentParser.sha(text),parseBudget,()->false);extracted=new MaterialParser.Result(parsed.format(),source.hash(),parsed.units(),parsed.textBytes());}catch(MaterialParser.ParseFailure invalid){throw failure(422,"KNOWLEDGE_DOCUMENT_INVALID");}}
  var parsed=parse(actor,meeting,scope,source,extracted,trace);
  var preparation=authority.publicationWriteGuard().prepare(actor,meeting);
  return authority.transactionRunner().required(()->{
   var gate=registry.lock(actor,meeting,MeetingAccess.Action.EDIT);var guard=authority.publicationWriteGuard().controls(preparation,actor,meeting,registry.access(gate));var replay=receipt(meeting,scope,request);if(replay!=null)return replay;fence(meeting,started.root());
   var existing=active(meeting);if(existing.size()>=MAX_MATERIALS)throw failure(422,"MATERIAL_LIMIT_EXCEEDED");
   if(existing.stream().anyMatch(r->source.file().equals(r.get("content_file_id"))||source.external()!=null&&source.external().equals(r.get("external_id"))&&source.version().equals(r.get("external_version"))))throw failure(409,"MATERIAL_ALREADY_SELECTED");
   String material=id(),revision=id(),document=id();j.update("INSERT INTO material_reference(id,meeting_id,kind,provider_id,external_id,file_id,state) VALUES (?,?,?,?,?,?,'ACTIVE')",material,meeting,source.provider()==null?"LOCAL":"KNOWLEDGE",source.provider(),source.external(),source.provider()==null?source.file():null);
   insertRevision(material,revision,1,document,source,parsed);bind(gate,actor,meeting,guard,revision,document,source,parsed);snapshot(meeting);j.update("INSERT INTO material_command_receipt VALUES(?,?,?,?,?)",meeting,scope,request,material,revision);return item(material,revision);
  });
 }
 public Item retry(Actor actor,String meeting,String material,String key,String trace)throws IOException {
  uuid(meeting);uuid(material);JdbcProcessingIntake.key(key);String scope=JdbcProcessingIntake.digest(actor.enterpriseId(),meeting,"MATERIAL_RETRY",key),request=JdbcProcessingIntake.digest(material);
  var started=start(actor,meeting,scope,request,material);if(started.replay()!=null)return started.replay();var prior=started.prior();if(!"FAILED".equals(prior.get("parse_state"))&&!"UNSUPPORTED".equals(prior.get("parse_state")))throw failure(409,"MATERIAL_NOT_FAILED");
  var source=new Source((String)prior.get("content_file_id"),(String)prior.get("content_hash"),(String)prior.get("display_name"),(String)prior.get("provider_id"),(String)prior.get("external_id"),(String)prior.get("external_version"));
  // Knowledge retries parse the exact retained, already authorized version; never follow latest.
  MaterialParser.Result extracted=null;if(source.provider()!=null){try(var original=registry.download(actor,source.file(),null)){var payload=ControlledKnowledgeClient.parse(original.body().readNBytes(Math.toIntExact(Math.min(parseBudget.sourceBytes(),8388608))+1),8388608);byte[] text=MaterialKnowledge.text(payload).getBytes(StandardCharsets.UTF_8);try{var value=parser.parse(new ByteArrayInputStream(text),"knowledge.txt",MaterialDocumentParser.sha(text),parseBudget,()->false);extracted=new MaterialParser.Result(value.format(),source.hash(),value.units(),value.textBytes());}catch(MaterialParser.ParseFailure invalid){throw failure(422,"KNOWLEDGE_DOCUMENT_INVALID");}}}
  var parsed=parse(actor,meeting,scope,source,extracted,trace);var preparation=authority.publicationWriteGuard().prepare(actor,meeting);
  return authority.transactionRunner().required(()->{var gate=registry.lock(actor,meeting,MeetingAccess.Action.EDIT);var guard=authority.publicationWriteGuard().controls(preparation,actor,meeting,registry.access(gate));var replay=receipt(meeting,scope,request);if(replay!=null)return replay;fence(meeting,started.root());var current=selected(meeting,material);if(!prior.get("revision_id").equals(current.get("revision_id")))throw failure(409,"MATERIAL_REVISION_CONFLICT");String revision=id(),document=id();insertRevision(material,revision,((Number)prior.get("revision")).longValue()+1,document,source,parsed);bind(gate,actor,meeting,guard,revision,document,source,parsed);snapshot(meeting);j.update("INSERT INTO material_command_receipt VALUES(?,?,?,?,?)",meeting,scope,request,material,revision);return item(material,revision);});
 }
 public void remove(Actor actor,String meeting,String material){uuid(meeting);uuid(material);var preparation=authority.publicationWriteGuard().prepare(actor,meeting);authority.transactionRunner().required(()->{var gate=registry.lock(actor,meeting,MeetingAccess.Action.EDIT);var guard=authority.publicationWriteGuard().controls(preparation,actor,meeting,registry.access(gate));var rows=j.queryForList("SELECT state FROM material_reference WHERE id=? AND meeting_id=? FOR UPDATE",material,meeting);if(rows.size()!=1)throw new NotFound();if("REMOVED".equals(rows.getFirst().get("state")))return null;active(meeting);claim(actor,meeting,gate,guard);j.update("UPDATE material_reference SET state='REMOVED' WHERE id=?",material);snapshot(meeting);return null;});}
 private Started start(Actor actor,String meeting,String scope,String request,String material){return authority.transactionRunner().required(()->{registry.lock(actor,meeting,MeetingAccess.Action.EDIT);var replay=receipt(meeting,scope,request);return new Started(root(meeting),replay,replay==null&&material!=null?selected(meeting,material):null);});}
 private Parse parse(Actor actor,String meeting,String scope,Source source,MaterialParser.Result extracted,String trace)throws IOException {
  try{MaterialParser.Result result=extracted;if(result==null)try(var download=registry.download(actor,source.file(),null)){if(download.length()>parseBudget.sourceBytes())return new Parse(null,"SOURCE_BYTES_EXCEEDED",null);long deadline=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(25);result=parser.parse(download.body(),source.name(),source.hash(),parseBudget,()->System.nanoTime()-deadline>=0);}
   return new Parse(result,null,store(actor,meeting,scope,"text","material-text.txt",result.textBytes(),trace));
  }catch(MaterialParser.ParseFailure invalid){if(invalid.code().equals("CANCELLED"))throw failure(503,"MATERIAL_PARSE_CANCELLED");return new Parse(null,invalid.code(),null);}
 }
 private String store(Actor actor,String meeting,String scope,String role,String name,byte[] bytes,String trace){String hash=MaterialDocumentParser.sha(bytes);var accepted=uploads.begin(actor,meeting,JdbcProcessingIntake.digest(scope,role,hash),new Begin(MaterialFileReferencePolicy.PURPOSE,name,bytes.length,hash),trace);var parts=new ArrayList<ClientPart>();for(int offset=0,number=1;offset<bytes.length;number++){int n=(int)Math.min(accepted.partSize(),bytes.length-offset);byte[] part=Arrays.copyOfRange(bytes,offset,offset+n);String ph=MaterialDocumentParser.sha(part);uploads.part(actor,accepted.uploadId(),number,new ByteArrayInputStream(part),n,ph,trace);parts.add(new ClientPart(number,ph));offset+=n;}return uploads.complete(actor,accepted.uploadId(),new Completion(parts,hash),trace).fileId();}
 private void insertRevision(String material,String revision,long number,String document,Source source,Parse parsed){String state=parsed.result()==null?"FAILED":"READY";j.update("INSERT INTO material_revision(id,reference_id,revision,external_version,content_file_id,content_hash,parse_state,created_at) VALUES(?,?,?,?,?,?,?,?)",revision,material,number,source.version(),source.file(),source.hash(),state,java.sql.Timestamp.from(Instant.now()));j.update("INSERT INTO parsed_document(id,material_revision_id,parser_version,text_file_id,state,unit_count,error_code) VALUES(?,?,?,?,?,?,?)",document,revision,parsed.result()==null?MaterialParser.PROFILE:MaterialProfiles.parser(parsed.result().format()),parsed.textFile(),state,parsed.result()==null?0:parsed.result().units().size(),parsed.error());if(parsed.result()!=null){var profile=MaterialArchives.ref(MaterialArchives.parser(parsed.result().format()));j.update("INSERT INTO parsed_document_profile VALUES(?,?,?,?)",document,parsed.result().format(),profile.version(),profile.sha256());for(var unit:parsed.result().units())j.update("INSERT INTO parsed_unit(document_id,ordinal,kind,page_no,paragraph_no,section_path,body) VALUES(?,?,?,?,?,?,?)",document,unit.ordinal(),unit.kind(),unit.pageNo(),unit.paragraphNo(),unit.sectionPath(),unit.body());}}
 private void bind(FileRegistry.LockedMeeting gate,Actor actor,String meeting,PublicationWriteGuard.Held guard,String revision,String document,Source source,Parse parsed){var files=new TreeMap<String,FileRegistry.LockedReference>();files.put(source.file(),registry.prelock(gate,new FileRegistry.Reference(MaterialFileReferencePolicy.CONTENT,revision,MaterialFileReferencePolicy.PURPOSE),source.file()));if(parsed.textFile()!=null)files.put(parsed.textFile(),registry.prelock(gate,new FileRegistry.Reference(MaterialFileReferencePolicy.TEXT,document,MaterialFileReferencePolicy.PURPOSE),parsed.textFile()));var ids=List.copyOf(files.keySet());var held=registry.prelockSources(gate,ids,false).orElseThrow(NotFound::new);var originals=registry.sources(gate,held,ids);var bindings=new ArrayList<FileRegistry.Binding>();for(var original:originals){if(!MaterialFileReferencePolicy.PURPOSE.equals(original.originalPurpose()))throw new NotFound();bindings.add(new FileRegistry.Binding(files.get(original.file().fileId()),original.file().locationRevision(),original.uploadId()));}claim(actor,meeting,gate,guard);registry.bindAll(held,bindings);}
 private void claim(Actor actor,String meeting,FileRegistry.LockedMeeting gate,PublicationWriteGuard.Held guard){var tasks=j.queryForList("SELECT id,state FROM durable_task WHERE subject_kind='MEETING' AND subject_id=? ORDER BY id LIMIT 257 FOR UPDATE",meeting);if(tasks.size()>256)throw failure(422,"MATERIAL_TASK_BUDGET_EXCEEDED");if(tasks.stream().anyMatch(t->Set.of("READY","RUNNING","RECONCILING").contains(t.get("state"))))throw failure(409,"MATERIAL_PROCESSING_ACTIVE");authority.publicationWriteGuard().tasks(guard,registry.access(gate));authority.publicationWriteGuard().claim(guard,registry.access(gate));}
 private void snapshot(String meeting){var rows=active(meeting);boolean failed=rows.stream().anyMatch(r->!"READY".equals(r.get("parse_state")));if(failed){advanceSnapshot(j,fences,meeting,null,true);return;}String snapshot=null;if(!rows.isEmpty()){snapshot=id();long number=j.queryForObject("SELECT COALESCE(MAX(revision),0)+1 FROM material_snapshot WHERE meeting_id=?",Long.class,meeting);String fingerprint=JdbcProcessingIntake.digest(rows.stream().map(r->r.get("revision_id")+":"+r.get("content_hash")).toArray(String[]::new));j.update("INSERT INTO material_snapshot VALUES(?,?,?,?,UTC_TIMESTAMP(6))",snapshot,meeting,number,fingerprint);long ordinal=0;for(var row:rows)j.update("INSERT INTO material_snapshot_item VALUES(?,?,?)",snapshot,row.get("revision_id"),++ordinal);}advanceSnapshot(j,fences,meeting,snapshot,false);}
 static long advanceSnapshot(JdbcTemplate j,SubjectFencePort fences,String meeting,String snapshot,boolean failed){var subject=fences.lock(new SubjectRef("MEETING",meeting),false).orElseThrow();long revision=subject.businessVersion()+1;int changed;if(failed)changed=j.update("UPDATE meeting SET materials_pending=1,revision=?,needs_generation=1,generation_fingerprint=NULL,updated_at=UTC_TIMESTAMP(6) WHERE id=? AND revision=? AND cancel_epoch=?",revision,meeting,subject.businessVersion(),subject.cancelEpoch());else changed=j.update("UPDATE meeting SET material_snapshot_id=?,materials_pending=0,revision=?,needs_generation=1,generation_fingerprint=NULL,updated_at=UTC_TIMESTAMP(6) WHERE id=? AND revision=? AND cancel_epoch=?",snapshot,revision,meeting,subject.businessVersion(),subject.cancelEpoch());if(changed!=1)throw new IllegalStateException("Meeting revision changed while updating materials");fences.advance(subject,revision,subject.cancelEpoch(),false);return revision;}
 private List<Map<String,Object>> active(String meeting){var rows=j.queryForList("SELECT m.id,m.provider_id,m.external_id,r.id revision_id,r.revision,r.external_version,r.content_file_id,r.content_hash,r.parse_state FROM material_reference m JOIN material_revision r ON r.reference_id=m.id WHERE m.meeting_id=? AND m.state='ACTIVE' AND NOT EXISTS(SELECT 1 FROM material_revision newer WHERE newer.reference_id=m.id AND newer.revision>r.revision) ORDER BY r.created_at,m.id LIMIT 65 FOR UPDATE",meeting);if(rows.size()>MAX_MATERIALS)throw failure(422,"MATERIAL_LIMIT_EXCEEDED");return rows;}
 private Map<String,Object> selected(String meeting,String material){return active(meeting).stream().filter(r->material.equals(r.get("id"))).findFirst().map(r->{var copy=new HashMap<>(r);copy.put("display_name",j.queryForObject("SELECT display_name FROM upload_session WHERE completed_file_id=? AND state='COMPLETED'",String.class,r.get("content_file_id")));return copy;}).orElseThrow(NotFound::new);}
 private Root root(String meeting){var row=j.queryForMap("SELECT revision,cancel_epoch,material_snapshot_id FROM meeting WHERE id=?",meeting);return new Root(((Number)row.get("revision")).longValue(),((Number)row.get("cancel_epoch")).longValue(),(String)row.get("material_snapshot_id"));}
 private void fence(String meeting,Root expected){if(!root(meeting).equals(expected))throw failure(409,"REVISION_CONFLICT");}
 private Listing listing(String meeting){var root=root(meeting);var rows=active(meeting);return new Listing(rows.stream().map(r->item((String)r.get("id"),(String)r.get("revision_id"))).toList(),root.snapshot(),rows.stream().anyMatch(r->!"READY".equals(r.get("parse_state"))),Long.toString(root.revision()));}
 private Item receipt(String meeting,String scope,String request){var rows=j.queryForList("SELECT request_hash,material_id,material_revision_id FROM material_command_receipt WHERE meeting_id=? AND scope_hash=?",meeting,scope);if(rows.isEmpty())return null;var row=rows.getFirst();if(!request.equals(row.get("request_hash")))throw failure(409,"IDEMPOTENCY_CONFLICT");return item((String)row.get("material_id"),(String)row.get("material_revision_id"));}
 private Item item(String material,String revision){var row=j.queryForMap("SELECT m.kind,r.external_version,r.content_file_id,r.content_hash,r.parse_state,d.id document_id,d.error_code,u.display_name,u.expected_size FROM material_reference m JOIN material_revision r ON r.reference_id=m.id JOIN parsed_document d ON d.material_revision_id=r.id JOIN upload_session u ON u.completed_file_id=r.content_file_id AND u.state='COMPLETED' WHERE m.id=? AND r.id=?",material,revision);return new Item(material,revision,(String)row.get("document_id"),(String)row.get("content_file_id"),(String)row.get("display_name"),(String)row.get("kind"),(String)row.get("external_version"),row.get("expected_size").toString(),(String)row.get("content_hash"),(String)row.get("parse_state"),(String)row.get("error_code"));}
 private static String id(){return UUID.randomUUID().toString();}
 static ama.contract.TranscriptContracts.Failure failure(int status,String code){return new ama.contract.TranscriptContracts.Failure(status,code);}
}
